function ProtectedAdmin() { const { user } = useApp(); return user ? <Routes><Route path="*" element={<AdminPage />} /></Routes> : <Navigate to="/admin/login" replace />; }

export default function App() { return <Routes><Route path="/" element={<Landing />} /><Route path="/benefits" element={<BenefitsPage />} /><Route path="/about" element={<AboutPage />} /><Route path="/access" element={<Access />} /><Route path="/customer/login" element={<CustomerLogin />} /><Route path="/admin/login" element={<AdminLogin />} /><Route path="/store" element={<Store />} /><Route path="/product/:id" element={<ProductDetailApi />} /><Route path="/cart" element={<CartPage />} /><Route path="/checkout" element={<Checkout />} /><Route path="/confirmation" element={<Confirmation />} /><Route path="/admin/*" element={<ProtectedAdmin />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes>; }
